import unittest

import main_download_fr_wikisource as dlws


class _FakeDownloader:
    def __init__(self, response_json):
        self.calls = []
        self._response_json = response_json

    def get_json(self, url, *, params=None, **_kwargs):
        self.calls.append({"params": dict(params or {}), "url": url})
        return self._response_json


def _page(title, content):
    return {
        "pageid": hash(title),
        "revisions": [{"slots": {"main": {"content": content}}}],
        "title": title,
    }


class WikisourceDownloadTests(unittest.TestCase):
    def test_download_chapter_batch_calls_action_api_with_batched_titles(self):
        chapter_plans = [("א", "יהושע_א/טעמים"), ("ב", "יהושע_ב/טעמים")]
        downloader = _FakeDownloader(
            {
                "query": {
                    "pages": [
                        _page("יהושע_א/טעמים", "line a\nline b\n"),
                        _page("יהושע_ב/טעמים", "line c\n"),
                    ]
                }
            }
        )

        chapter_lines = dlws._download_chapter_batch(chapter_plans, downloader)

        self.assertEqual(dlws._WIKISOURCE_API_PHP, downloader.calls[0]["url"])
        self.assertEqual("query", downloader.calls[0]["params"]["action"])
        self.assertEqual("revisions", downloader.calls[0]["params"]["prop"])
        self.assertEqual("content", downloader.calls[0]["params"]["rvprop"])
        self.assertEqual("main", downloader.calls[0]["params"]["rvslots"])
        self.assertEqual(
            "יהושע_א/טעמים|יהושע_ב/טעמים", downloader.calls[0]["params"]["titles"]
        )
        self.assertEqual({"א": ["line a", "line b"], "ב": ["line c"]}, chapter_lines)

    def test_chapter_lines_follow_requested_order_not_response_order(self):
        chapter_plans = [("א", "יהושע_א/טעמים"), ("ב", "יהושע_ב/טעמים")]
        response_json = {
            "query": {
                "pages": [
                    _page("יהושע_ב/טעמים", "line c\n"),
                    _page("יהושע_א/טעמים", "line a\nline b\n"),
                ]
            }
        }

        chapter_lines = dlws._chapter_lines_from_response_json(
            response_json, chapter_plans
        )

        self.assertEqual(["א", "ב"], list(chapter_lines))
        self.assertEqual(["line a", "line b"], chapter_lines["א"])
        self.assertEqual(["line c"], chapter_lines["ב"])

    def test_chapter_lines_resolve_normalized_and_redirected_titles(self):
        chapter_plans = [("יא", "ספר_שמואל_ב/יא/טעמים")]
        response_json = {
            "query": {
                "normalized": [
                    {
                        "from": "ספר_שמואל_ב/יא/טעמים",
                        "to": "ספר שמואל ב/יא/טעמים",
                    }
                ],
                "redirects": [
                    {
                        "from": "ספר שמואל ב/יא/טעמים",
                        "to": 'ספר שמואל/שמ"ב יא',
                    }
                ],
                "pages": [_page('ספר שמואל/שמ"ב יא', "line a\n")],
            }
        }

        chapter_lines = dlws._chapter_lines_from_response_json(
            response_json, chapter_plans
        )

        self.assertEqual({"יא": ["line a"]}, chapter_lines)

    def test_chapter_lines_raise_for_missing_page(self):
        chapter_plans = [("א", "יהושע_א/טעמים")]
        response_json = {
            "query": {
                "pages": [
                    {
                        "missing": True,
                        "title": "יהושע_א/טעמים",
                    }
                ]
            }
        }

        with self.assertRaises(AssertionError):
            dlws._chapter_lines_from_response_json(response_json, chapter_plans)


